```typescript
import { ITechnicalInventory } from '../types/technical-inventory';

export interface SkipDecision {
  skip: boolean;
  reason?: string;
}

export function computeInventorySkips(inventory: ITechnicalInventory | undefined): Map<string, SkipDecision> {
  const skipDecisions = new Map<string, SkipDecision>();

  if (!inventory) {
    // If inventory collection failed, don't skip anything
    return skipDecisions;
  }

  // Database patterns coverage skip rule
  const hasDbDeps = inventory.dependencies?.some(dep => 
    ['postgres', 'mysql', 'mongo', 'prisma', 'typeorm'].some(dbTerm => 
      dep.name.toLowerCase().includes(dbTerm)
    )
  );
  const hasDbFiles = inventory.filePatterns?.some(pattern =>
    pattern.includes('migration') || pattern.includes('orm') || 
    pattern.includes('seed') || pattern.includes('repository')
  );
  const hasDbServices = inventory.dockerServices?.some(service =>
    service.image?.toLowerCase().includes('postgres') || 
    service.image?.toLowerCase().includes('mysql') ||
    service.image?.toLowerCase().includes('mongo')
  );

  skipDecisions.set('database-patterns-coverage', {
    skip: !hasDbDeps && !hasDbFiles && !hasDbServices,
    reason: !hasDbDeps && !hasDbFiles && !hasDbServices 
      ? 'No database dependencies, migration/ORM/seed/repository files, or database Docker services detected'
      : undefined
  });

  // Test patterns coverage skip rule
  const hasTestDeps = inventory.dependencies?.some(dep =>
    ['jest', 'vitest', 'mocha', 'pytest'].some(testTerm =>
      dep.name.toLowerCase().includes(testTerm)
    )
  );
  const hasTestFiles = inventory.filePatterns?.some(pattern =>
    pattern.includes('.test.') || pattern.includes('.spec.')
  );
  const hasMockPatterns = inventory.filePatterns?.some(pattern =>
    pattern.includes('mock') || pattern.includes('fixture')
  );

  skipDecisions.set('test-patterns-coverage', {
    skip: !hasTestDeps && !hasTestFiles && !hasMockPatterns,
    reason: !hasTestDeps && !hasTestFiles && !hasMockPatterns
      ? 'No test dependencies, test files (.test.*, .spec.*), or mock/fixture patterns detected'
      : undefined
  });

  // Security skip rule
  const hasEnvVars = inventory.envVars && inventory.envVars.length > 0;
  const hasConfigFiles = inventory.filePatterns?.some(pattern =>
    pattern.includes('config') || pattern.endsWith('.env') || pattern.endsWith('.json')
  );
  const hasDependencies = inventory.dependencies && inventory.dependencies.length > 0;

  skipDecisions.set('security', {
    skip: !hasEnvVars && !hasConfigFiles && !hasDependencies,
    reason: !hasEnvVars && !hasConfigFiles && !hasDependencies
      ? 'No environment variables, config files, or dependencies detected (minimal repository)'
      : undefined
  });

  return skipDecisions;
}
```

